const READ_MODEL_LOCALIZED_KEYS = new Set([
  'stage',
  'outcome',
  'requirement',
  'evidence',
  'label',
  'description',
  'managerQuestion',
  'protocol',
  'managerMeaning',
  'phase',
  'detail',
  'title',
  'summary',
  'proof',
  'actionLabel',
]);

function localizeReadModel(value, language = 'en', key = '') {
  const currentLanguage = normalizeLanguage(language);
  if (typeof value === 'string') {
    return READ_MODEL_LOCALIZED_KEYS.has(key) ? localizeText(value, currentLanguage) : value;
  }
  if (Array.isArray(value)) return value.map((item) => localizeReadModel(item, currentLanguage, key));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([childKey, item]) => [childKey, localizeReadModel(item, currentLanguage, childKey)]));
  }
  return value;
}

function materializeActionTemplate(value, now = nowIso()) {
  if (Array.isArray(value)) return value.map((item) => materializeActionTemplate(item, now));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, materializeActionTemplate(item, now)]));
  }
  return value === 'now-iso' ? now : value;
}

function extractAgentIdFromActionPath(path = '') {
  return String(path || '').match(/\/agents\/([^/]+)\/work-cycle$/)?.[1] || null;
}

function extractKickoffActionFromPath(path = '') {
  const parts = String(path || '').split('/').filter(Boolean);
  if (parts[0] !== 'kickoff-meetings') return null;
  return {
    meetingId: parts[1] || null,
    action: parts[2] || 'create',
  };
}

function commandShouldRequestModelIntent(command = '') {
  return /^POST\s+/i.test(command)
    && !/\/llm\//i.test(command)
    && !/\/manager-flow-graph\/nodes\/[^/]+\/confirm/i.test(command);
}

function compactModelIntent(value = {}) {
  if (!value || typeof value !== 'object') return {};
  return Object.fromEntries(Object.entries(value).filter(([, item]) => (
    item !== undefined
    && item !== null
    && (!(Array.isArray(item)) || item.length > 0)
    && (!(typeof item === 'string') || item.trim())
  )));
}

function modelIntentSummary(record = {}) {
  const intent = record.intent || {};
  if (typeof intent.intent === 'string' && intent.intent.trim()) return intent.intent.trim();
  if (typeof record.content === 'string' && record.content.trim()) return record.content.trim().slice(0, 220);
  if (record.error) return `Model intent failed: ${record.error}`;
  return 'Model intent recorded.';
}

function multiChannelSourceModeFor(channelId, sourceMode) {
  if (sourceMode) return sourceMode;
  return channelId === 'google_chat' ? 'google_chat' : 'war_room_meeting';
}

function multiChannelSourceLabelFor(sourceMode, channelId) {
  const normalizedMode = multiChannelSourceModeFor(channelId, sourceMode);
  if (normalizedMode === 'google_chat') return 'Google Chat';
  if (normalizedMode === 'war_room_meeting') return 'War Room';
  return normalizedMode || channelId || 'Source';
}

export function buildPeerManagementMatrix(team = [], { leaderId, reviewerId } = {}) {
  const agents = team.filter((agent) => agent?.id);
  if (agents.length <= 1) {
    return agents.map((agent) => ({
      agentId: agent.id,
      peerManagedIds: [],
      peerManagerIds: [],
      peerIds: [],
    }));
  }

  const orderedAgents = [
    ...agents.filter((agent) => agent.id === leaderId),
    ...agents.filter((agent) => agent.id === reviewerId && agent.id !== leaderId),
    ...agents.filter((agent) => agent.id !== leaderId && agent.id !== reviewerId),
  ];
  const peerManagedByAgent = new Map(orderedAgents.map((agent) => [agent.id, []]));
  const peerManagersByAgent = new Map(orderedAgents.map((agent) => [agent.id, []]));

  orderedAgents.forEach((agent, index) => {
    const target = orderedAgents[(index + 1) % orderedAgents.length];
    if (!target || target.id === agent.id) return;
    peerManagedByAgent.set(agent.id, uniqueStrings([...(peerManagedByAgent.get(agent.id) || []), target.id]));
    peerManagersByAgent.set(target.id, uniqueStrings([...(peerManagersByAgent.get(target.id) || []), agent.id]));
  });

  return agents.map((agent) => ({
    agentId: agent.id,
    peerManagedIds: peerManagedByAgent.get(agent.id) || [],
    peerManagerIds: peerManagersByAgent.get(agent.id) || [],
    peerIds: agents.filter((peer) => peer.id !== agent.id).map((peer) => peer.id),
  }));
}

export function applyPeerManagementMatrix({
  project = {},
  leaderId,
  reviewerId,
  now = nowIso(),
} = {}) {
  const team = project.team || [];
  const matrixRows = buildPeerManagementMatrix(team, { leaderId, reviewerId });
  const matrixByAgentId = Object.fromEntries(matrixRows.map((row) => [row.agentId, row]));
  const previousStates = project.agentStates || {};
  const nextTeam = team.map((agent) => {
    const row = matrixByAgentId[agent.id] || {};
    return {
      ...agent,
      peerManagedIds: uniqueStrings([...(agent.peerManagedIds || []), ...(row.peerManagedIds || [])]),
      peerManagerIds: uniqueStrings([...(agent.peerManagerIds || []), ...(row.peerManagerIds || [])]),
      peerIds: uniqueStrings([...(agent.peerIds || []), ...(row.peerIds || [])]),
    };
  });
  const nextStates = Object.fromEntries(nextTeam.map((agent) => {
    const previous = previousStates[agent.id] || {};
    return [agent.id, {
      ...previous,
      agentId: agent.id,
      name: previous.name || agent.name,
      role: previous.role || agent.role || agent.title || 'Agent',
      managerId: previous.managerId || (agent.id === leaderId ? null : leaderId || agent.managerId || null),
      managedIds: uniqueStrings([...(previous.managedIds || []), ...(agent.managedIds || [])]),
      peerManagedIds: uniqueStrings([...(previous.peerManagedIds || []), ...(matrixByAgentId[agent.id]?.peerManagedIds || [])]),
      peerManagerIds: uniqueStrings([...(previous.peerManagerIds || []), ...(matrixByAgentId[agent.id]?.peerManagerIds || [])]),
      peerManagerId: previous.peerManagerId || matrixByAgentId[agent.id]?.peerManagerIds?.[0] || null,
      peerIds: uniqueStrings([...(previous.peerIds || []), ...(matrixByAgentId[agent.id]?.peerIds || [])]),
      currentPlan: previous.currentPlan || null,
      inbox: previous.inbox || [],
      obligations: previous.obligations || [],
      taskIds: previous.taskIds || [],
      worklog: previous.worklog || [],
      status: previous.status || 'standing-by',
      peerManagementEstablishedAt: previous.peerManagementEstablishedAt || now,
    }];
  }));

  return {
    ...project,
    team: nextTeam,
    agentStates: {
      ...previousStates,
      ...nextStates,
    },
    peerManagementMatrix: matrixRows,
  };
}

function taskBelongsToAgent(task = {}, agent = {}) {
  return task.ownerId === agent.id
    || task.assignee === agent.id
    || task.assignee === agent.name;
}

function openAgentTask(project = {}, agent = {}, preferredTaskId = null) {
  const tasks = project.tasks || [];
  if (preferredTaskId) {
    const preferredTask = tasks.find((task) => String(task.id || '') === String(preferredTaskId));
    if (preferredTask && taskBelongsToAgent(preferredTask, agent) && preferredTask.status !== 'done') return preferredTask;
  }
  return tasks.find((task) => taskBelongsToAgent(task, agent) && task.status !== 'done') || null;
}

function safeDateMs(value, fallback = Date.now()) {
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function agentWorkIntervalMs(project = {}, state = {}, intervalMs) {
  const configuredMinutes = state.workCadenceMinutes
    || project.agentAutonomy?.intervalMinutes
    || project.autonomy?.agentIntervalMinutes;
  const configuredMs = Number(configuredMinutes) > 0 ? Number(configuredMinutes) * 60 * 1000 : null;
  return intervalMs || configuredMs || DEFAULT_AGENT_WORK_INTERVAL_MS;
}

function agentManagementPriority({ project = {}, agent = {}, state = {} } = {}) {
  const team = project.team || [];
  const openTasks = (project.tasks || []).filter((task) => taskBelongsToAgent(task, agent) && task.status !== 'done');
  const inboxItems = state.inbox || [];
  const obligations = (state.obligations || []).filter((obligation) => obligation.status !== 'done' && obligation.status !== 'resolved');
  const managerIds = [
    state.managerId,
    ...(state.peerManagerIds || []),
  ].filter(Boolean);
  const managerNames = managerIds
    .map((managerId) => team.find((member) => member.id === managerId)?.name || managerId)
    .filter(Boolean);
  const managerRefs = new Set([...managerIds, ...managerNames]);
  const directManagementInbox = inboxItems.filter((item) => (
    ['management-check-in', 'peer-management-check-in', 'review-sweep', 'change-sync'].includes(item.source)
    || managerRefs.has(item.from)
    || /management check-in|peer-management|review sweep|plan updated/i.test(item.text || '')
  ));
  const peerDependencyCount = (project.peerHandoffs || [])
    .filter((handoff) => handoff.targetId === agent.id && handoff.status === 'accepted')
    .length;
  const reviewTargetCount = (project.logs || [])
    .filter((log) => log.eventType === 'review-sweep' && (log.targetAgentId === agent.id || log.agentId === agent.id))
    .length;
  const reasons = [
    openTasks.length ? `${openTasks.length} open owned task${openTasks.length === 1 ? '' : 's'}` : null,
    obligations.length ? `${obligations.length} open obligation${obligations.length === 1 ? '' : 's'}` : null,
    directManagementInbox.length ? `${directManagementInbox.length} management inbox signal${directManagementInbox.length === 1 ? '' : 's'}` : null,
    managerNames.length ? `managed by ${managerNames.join(' / ')}` : null,
    peerDependencyCount ? `${peerDependencyCount} peer dependency handoff${peerDependencyCount === 1 ? '' : 's'}` : null,
    reviewTargetCount ? `${reviewTargetCount} review sweep signal${reviewTargetCount === 1 ? '' : 's'}` : null,
  ].filter(Boolean);

  return {
    score: (openTasks.length * 30)
      + (obligations.length * 20)
      + (directManagementInbox.length * 18)
      + (managerIds.length * 12)
      + (peerDependencyCount * 14)
      + (reviewTargetCount * 8),
    reasons,
    managerIds,
    managedBy: managerNames,
    openTaskCount: openTasks.length,
    obligationCount: obligations.length,
    managementInboxCount: directManagementInbox.length,
    peerDependencyCount,
    reviewTargetCount,
  };
}

function slugifyArtifactPart(value = 'artifact', maxLength = 48) {
  const length = Math.max(8, Math.min(Number(maxLength) || 48, 96));
  return String(value || 'artifact')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, length) || 'artifact';
}

function shortArtifactHash(value = 'artifact') {
  return persistenceChecksum(value).replace(/^chk_/, '').slice(0, 10);
}

function buildAgentArtifactDraft({
  project = {},
  agent = {},
  task = null,
  workText = '',
  workSummary = '',
  now = nowIso(),
  completed = false,
  cycleId = '',
} = {}) {
  const projectSlug = slugifyArtifactPart(project.id || project.name || 'project', 32);
  const agentSlug = slugifyArtifactPart(agent.name || agent.id || 'agent', 24);
  const taskSlug = slugifyArtifactPart(task?.text || workText || 'work', 28);
  const fileName = `${agentSlug}-${taskSlug}-${shortArtifactHash({
    projectId: project.id || null,
    agentId: agent.id || null,
    taskId: task?.id || null,
    taskText: task?.text || workText || '',
    now,
  })}.md`;
  const relativePath = `agent-artifacts/${projectSlug}/${fileName}`;
  const content = [
    `# ${task?.text || workText || 'Agent work artifact'}`,
    '',
    `Project: ${project.name || project.id || 'Untitled project'}`,
    `Agent: ${agent.name || agent.id || 'Agent'}`,
    `Role: ${agent.role || agent.title || 'Agent'}`,
    `Status: ${completed ? 'completed' : 'in-progress'}`,
    `Created at: ${now}`,
    `Cycle: ${cycleId || 'agent-work-cycle'}`,
    '',
    '## Work Summary',
    workSummary || 'Agent produced a durable work artifact for timeline review.',
    '',
    '## Next Evidence',
    completed
      ? 'This artifact is ready for manager review and downstream handoff.'
      : 'Continue the next work pulse, update this artifact, and publish timeline evidence.',
    '',
  ].join('\n');
  return {
    id: `artifact_${agent.id || agentSlug}_${Date.parse(now) || Date.now()}`,
    type: completed ? 'deliverable-artifact' : 'work-artifact',
    title: task?.text || workText || 'Agent work artifact',
    fileName,
    relativePath,
    path: relativePath,
    content,
    createdAt: now,
    agentId: agent.id || null,
    taskId: task?.id || null,
    cycleId,
    status: completed ? 'completed' : 'in-progress',
  };
}

function normalizeModelArtifactDraftPayload(value = {}) {
  if (!value || typeof value !== 'object') return {};
  return {
    title: redactSensitiveText(String(value.title || '').trim()),
    summary: redactSensitiveText(String(value.summary || '').trim()),
    body: redactSensitiveText(String(value.body || value.content || '').trim()),
    tags: uniqueStrings(Array.isArray(value.tags) ? value.tags : []).map((tag) => redactSensitiveText(tag)).slice(0, 8),
  };
}

function buildArtifactDraftQualityGate({
  id,
  label,
  passed,
  detail,
  severity = 'required',
} = {}) {
  return {
    id,
    label,
    passed: Boolean(passed),
    status: passed ? 'passed' : 'failed',
    severity,
    detail,
  };
}

function evaluateAgentArtifactDraftQuality({
  artifactType = 'progress-brief',
  title = '',
  summary = '',
  body = '',
  task = null,
  evidenceSearches = [],
  priorSubmissions = [],
  reviews = [],
  modelUsed = false,
  modelResult = null,
  modelStatus = {},
  source = 'local-artifact-draft-generator',
  generationProvenance = null,
  now = nowIso(),
} = {}) {
  const cleanTitle = redactSensitiveText(String(title || ''));
  const cleanSummary = redactSensitiveText(String(summary || ''));
  const cleanBody = redactSensitiveText(String(body || ''));
  const combined = `${cleanTitle}\n${cleanSummary}\n${cleanBody}`;
  const lowered = combined.toLowerCase();
  const leakScan = scanTextForRawSecretLeaks(combined);
  const genericSignals = [
    /product[- ]team/.test(lowered),
    /manager/.test(lowered),
    /artifact|submission|handoff|workflow/.test(lowered),
  ];
  const researchOnlyMarkerPresent = /research-only|paper-only|论文专用/.test(lowered);
  const researchOnlyMarkerNegated = /\b(?:not|without|avoid(?:s|ing)?|prevent(?:s|ing)?)\s+(?:becoming\s+|turning\s+into\s+|being\s+|an?\s+)*(?:research-only|paper-only)\b/.test(lowered);
  const sourceSignals = [
    task?.id,
    evidenceSearches.length,
    priorSubmissions.length,
    reviews.length,
  ].filter(Boolean).length;
  const bodyWordCount = cleanBody.split(/\s+/).filter(Boolean).length;
  const gates = [
    buildArtifactDraftQualityGate({
      id: 'draft-title-summary-body',
      label: 'Draft has title, summary, and body',
      passed: cleanTitle.length >= 8 && cleanSummary.length >= 24 && bodyWordCount >= 60,
      detail: `title=${cleanTitle.length} chars, summary=${cleanSummary.length} chars, body=${bodyWordCount} words.`,
    }),
    buildArtifactDraftQualityGate({
      id: 'generic-product-team-language',
      label: 'Draft stays generic to product-team work',
      passed: genericSignals.filter(Boolean).length >= 2 && (!researchOnlyMarkerPresent || researchOnlyMarkerNegated),
      detail: `${genericSignals.filter(Boolean).length}/3 generic product-team signal(s) present; research-only marker ${researchOnlyMarkerPresent ? (researchOnlyMarkerNegated ? 'negated' : 'present') : 'absent'}.`,
    }),
    buildArtifactDraftQualityGate({
      id: 'task-evidence-review-context',
      label: 'Draft links to task, evidence, prior work, or review context',
      passed: sourceSignals >= 2,
      detail: `${sourceSignals}/4 context channel(s) present.`,
    }),
    buildArtifactDraftQualityGate({
      id: 'manager-review-handoff',
      label: 'Draft includes manager or reviewer handoff',
      passed: /handoff|reviewer|manager|review/.test(lowered),
      detail: 'Draft must make the next review or manager handoff explicit.',
    }),
    buildArtifactDraftQualityGate({
      id: 'artifact-type-aligned',
      label: 'Draft artifact type is explicit',
      passed: lowered.includes(String(artifactType || '').replace(/-/g, ' ')) || lowered.includes(String(artifactType || '')),
      detail: `artifactType=${artifactType}.`,
    }),
    buildArtifactDraftQualityGate({
      id: 'redaction-clean',
      label: 'Draft text passes raw-secret scan',
      passed: leakScan.count === 0,
      detail: `${leakScan.count} raw secret leak(s) detected.`,
    }),
    buildArtifactDraftQualityGate({
      id: 'model-provenance-ready',
      label: 'Model-backed draft has provider provenance or local fallback is explicit',
      passed: modelUsed
        ? Boolean(modelResult?.ok && (modelResult.provider || modelStatus.provider) && (modelResult.model || modelStatus.model))
        : source === 'local-artifact-draft-generator',
      detail: modelUsed
        ? `${modelResult?.provider || modelStatus.provider || 'unknown'} / ${modelResult?.model || modelStatus.model || 'unknown'}.`
        : 'Local fallback draft; model use was not required for this draft.',
    }),
  ];
  const failedRequiredGates = gates.filter((gate) => gate.severity === 'required' && !gate.passed);
  const score = Math.round((gates.filter((gate) => gate.passed).length / gates.length) * 100);
  const generationMode = generationProvenance?.generationMode
    || (modelUsed ? 'model-provider-output' : 'explicit-local-template');
  const computedQualityLevel = score >= 90 ? 'strong' : score >= 75 ? 'usable' : score >= 60 ? 'review-required' : 'blocked';
  const qualityLevel = generationMode === 'model-provider-output' ? computedQualityLevel : 'review-required';
  const structurallyReadyForReview = failedRequiredGates.length === 0;
  const qualityStatus = generationMode === 'requested-model-fallback'
    ? 'degraded-review-required'
    : generationMode === 'explicit-local-template'
      ? 'template-review-required'
      : structurallyReadyForReview
        ? 'local-quality-ready'
        : 'needs-review';
  return {
    schemaVersion: 'artifact-draft-quality/v1',
    status: qualityStatus,
    qualityScore: score,
    qualityLevel,
    structurallyReadyForReview,
    readyForLocalPilot: generationMode === 'model-provider-output' && structurallyReadyForReview,
    readyForProduction: false,
    humanReviewRequired: true,
    generationMode,
    qualityTier: generationProvenance?.qualityTier || (modelUsed ? 'model-draft' : 'local-template'),
    qualityCeiling: generationProvenance?.qualityCeiling || null,
    releaseEligibility: generationProvenance?.releaseEligibility || null,
    generationProvenanceChecksum: generationProvenance?.checksum || null,
    modelOutput: {
      used: Boolean(modelUsed),
      provider: modelResult?.provider || modelStatus.provider || null,
      model: modelResult?.model || modelStatus.model || null,
      responseId: modelResult?.id || modelResult?.responseId || null,
    },
    gates,
    failedGates: failedRequiredGates,
    requiredProductionControls: [
      {
        id: 'human-model-output-review',
        label: 'Human review for model-authored artifacts',
        status: modelUsed ? 'required-for-production' : 'not-required-for-local-fallback',
        detail: 'Production model-authored artifacts require calibrated Reviewer or Manager approval before release use.',
      },
      {
        id: 'model-quality-evaluation',
        label: 'Calibrated model output quality evaluation',
        status: 'blocked',
        detail: 'Production needs calibrated rubric, regression datasets, hallucination checks, and customer-specific acceptance policy.',
      },
      {
        id: 'model-output-retention-policy',
        label: 'Model output retention and audit policy',
        status: 'blocked',
        detail: 'Production needs retention, deletion, audit, and incident handling for prompt/output payloads.',
      },
    ],
    redaction: {
      rawLeakCount: leakScan.count,
      scanChecksum: persistenceChecksum(leakScan),
    },
    evaluatedAt: now,
    checksum: persistenceChecksum({
      artifactType,
      title: cleanTitle,
      summary: cleanSummary,
      body: cleanBody,
      modelUsed: Boolean(modelUsed),
      generationMode,
      generationProvenanceChecksum: generationProvenance?.checksum || null,
      score,
      gateRows: gates.map((gate) => [gate.id, gate.passed]),
      evaluatedAt: now,
    }),
  };
}

function buildAgentSubmissionDraft({
  project = {},
  agent = {},
  task = null,
  artifactType = 'progress-brief',
  instruction = '',
  evidenceSearches = [],
  priorSubmissions = [],
  reviews = [],
  now = nowIso(),
  modelPayload = {},
  modelResult = null,
  modelStatus = {},
  promptBoundary = null,
  generationProvenance = null,
  source = 'local-artifact-draft-generator',
} = {}) {
  const normalizedType = normalizeAgentSubmissionArtifactType(artifactType);
  const timestamp = Date.parse(now) || Date.now();
  const safeInstruction = redactSensitiveText(String(instruction || '').trim());
  const payload = normalizeModelArtifactDraftPayload(modelPayload);
  const typeLabel = normalizedType.replace(/-/g, ' ');
  const safeTitle = payload.title || `${agent.name || agent.id || 'Agent'} ${typeLabel}`;
  const safeSummary = payload.summary || [
    `${agent.name || 'Agent'} drafted a ${typeLabel} for ${project.name || project.id || 'this project'}.`,
    task ? `Linked task: ${task.text || task.id}.` : null,
  ].filter(Boolean).join(' ');
  const evidenceLines = evidenceSearches.length
    ? evidenceSearches.slice(0, 4).map((record) => `- ${record.query || record.id}: ${record.evidenceJudgement || record.qualitySummary?.judgement || 'evidence recorded'} (${record.sources?.length || 0} source(s))`)
    : ['- No external evidence search linked yet; use project transcript, task evidence, and reviewer feedback.'];
  const priorWorkLines = priorSubmissions.length
    ? priorSubmissions.slice(0, 6).map((submission) => `- ${submission.artifactType || 'artifact'}: ${submission.title || submission.id}`)
    : ['- No prior submission required for this draft.'];
  const reviewLines = reviews.length
    ? reviews.slice(0, 4).map((review) => `- ${review.verdict || review.status || 'review'}: ${compactPreview(review.comments || review.id || '', 180)}`)
    : ['- No open review obligation linked.'];
  const fallbackBody = [
    `# ${safeTitle}`,
    '',
    '## Context',
    safeInstruction || `Prepare a ${typeLabel} that advances the generic AI product-team workflow.`,
    '',
    '## Task',
    task ? `${task.text || task.title || task.id}` : 'No task was provided; draft is project-scoped.',
    '',
    '## Evidence And Prior Work',
    ...evidenceLines,
    '',
    '## Related Submissions',
    ...priorWorkLines,
    '',
    '## Review Signals',
    ...reviewLines,
    '',
    '## Draft Output',
    `This ${typeLabel} should be submitted as a manager-visible product-team artifact node with task, chat, timeline, event-ledger, workspace, and proof-map traceability.`,
    '',
    '## Handoff',
    'Submit to the Reviewer or Manager for the next review/revision step.',
  ].join('\n');
  const body = payload.body
    ? [
      payload.body,
      '',
      '## Product-Team Artifact Contract',
      `Artifact type: ${normalizedType} / ${typeLabel}.`,
      `Task context: ${task ? task.text || task.title || task.id : 'project-scoped draft'}.`,
      `Evidence context: ${evidenceSearches.length} linked evidence search(es).`,
      `Prior product-team artifacts: ${priorSubmissions.length} linked submission(s).`,
      'Reviewer/Manager handoff: submit this draft for review, requested changes, revision, and final deliverable closure.',
      'Production boundary: local MVP proof is allowed; public production still requires managed identity, persistence, queueing, provider audit, cost controls, and incident recovery.',
    ].join('\n')
    : fallbackBody;
  const proofContext = {
    taskId: task?.id || null,
    evidenceSearchIds: evidenceSearches.map((record) => record.id).filter(Boolean),
    submissionIds: priorSubmissions.map((submission) => submission.id).filter(Boolean),
    reviewIds: reviews.map((review) => review.id).filter(Boolean),
  };
  const artifactDraftQuality = evaluateAgentArtifactDraftQuality({
    artifactType: normalizedType,
    title: safeTitle,
    summary: safeSummary,
    body,
    task,
    evidenceSearches,
    priorSubmissions,
    reviews,
    modelUsed: Boolean(generationProvenance?.modelUsed),
    modelResult,
    modelStatus,
    source,
    generationProvenance,
    now,
  });
  const draft = {
    schemaVersion: 'agent-artifact-draft/v1',
    id: `artifact_draft_${project.id || 'project'}_${agent.id || 'agent'}_${normalizedType}_${timestamp}`,
    projectId: project.id || null,
    agentId: agent.id || null,
    agentName: agent.name || agent.id || null,
    artifactType: normalizedType,
    title: safeTitle,
    summary: safeSummary,
    body,
    taskId: task?.id || null,
    instruction: safeInstruction,
    source,
    modelUsed: Boolean(generationProvenance?.modelUsed),
    generationProvenance: generationProvenance ? publicModelGenerationProvenance(generationProvenance) : null,
    modelProvider: generationProvenance?.modelUsed ? {
      provider: modelResult.provider || modelStatus.provider || null,
      model: modelResult.model || modelStatus.model || null,
      responseId: modelResult.id || modelResult.responseId || null,
      usage: modelResult.usage || null,
    } : {
      provider: modelStatus.provider || null,
      model: modelStatus.model || null,
      enabled: Boolean(modelStatus.enabled),
      reason: generationProvenance?.degradationReason
        || (generationProvenance?.generationMode === 'explicit-local-template' ? 'model-not-requested' : 'provider-unavailable'),
    },
    promptBoundary: promptBoundary ? publicPromptBoundaryReceipt(promptBoundary) : null,
    tags: uniqueStrings([
      'agent-artifact-draft',
      normalizedType,
      ...(payload.tags || []),
    ]).slice(0, 10),
    sourceRefs: evidenceSearches.flatMap((record) => (record.sources || []).slice(0, 4)).map((sourceRef) => redactSensitiveObject(sourceRef)),
    proofContext,
    artifactDraftQuality,
    createdAt: now,
  };
  return {
    ...draft,
    checksum: persistenceChecksum({
      schemaVersion: draft.schemaVersion,
      projectId: draft.projectId,
      agentId: draft.agentId,
      artifactType: draft.artifactType,
      title: draft.title,
      summary: draft.summary,
      body: draft.body,
      proofContext: draft.proofContext,
      createdAt: draft.createdAt,
      source: draft.source,
      modelUsed: draft.modelUsed,
      generationProvenanceChecksum: draft.generationProvenance?.checksum || null,
      promptBoundaryChecksum: draft.promptBoundary?.checksum || null,
    }),
  };
}

function timelineCommitAreaKey(time = nowIso()) {
  const parsed = Date.parse(time);
  if (!Number.isFinite(parsed)) return String(time || 'unscheduled');
  const date = new Date(parsed);
  date.setSeconds(0, 0);
  return date.toISOString();
}

function buildAgentTimelineToolSubmission({
  project = {},
  agent = {},
  task = null,
  now = nowIso(),
  cycleId = '',
  completed = false,
  workText = '',
  workSummary = '',
  routine = null,
  artifactRecord = null,
  managementReasons = [],
  collaboratorIds = [],
  trigger = 'agent-worker',
  cadence = 'agent-pulse',
} = {}) {
  const thinkingFrame = {
    routineId: routine?.id || 'generalist-routine',
    routineLabel: routine?.label || 'Agent work routine',
    checklist: routine?.checklist || ['read latest state', 'choose next obligation', 'publish timeline evidence'],
    artifact: routine?.artifact || artifactRecord?.title || 'timeline evidence',
    intentSource: 'agent-current-plan',
  };
  const commitMessage = completed
    ? `${agent.name || 'Agent'} completed ${task?.text || workText || 'the assigned work'} and submitted the deliverable.`
    : `${agent.name || 'Agent'} published progress on ${task?.text || workText || 'the current work pulse'}.`;
  return {
    id: `timeline_submission_${agent.id || 'agent'}_${Date.parse(now) || Date.now()}`,
    tool: 'manager-flow-timeline',
    protocolVersion: 'agent-timeline-submit/v1',
    commitAreaKey: timelineCommitAreaKey(now),
    axis: 'x-time-single-axis',
    branchPolicy: 'same-time-small-branch',
    submittedAt: now,
    submittedByAgentId: agent.id || null,
    submittedByAgentName: agent.name || 'Agent',
    taskId: task?.id || null,
    cycleId,
    trigger,
    cadence,
    category: completed ? 'submission' : 'execution',
    subtype: completed ? 'deliverable-submit' : 'work-pulse-submit',
    intent: completed
      ? 'Agent completed the task and self-published a timeline commit for manager/user review.'
      : 'Agent used the timeline tool to publish a progress commit after its work pulse.',
    commitMessage,
    thinkingFrame,
    collaborationContext: {
      managerId: agent.managerId || null,
      collaboratorIds: uniqueStrings(collaboratorIds),
      managementReasons: uniqueStrings(managementReasons),
    },
    requiredFields: ['category', 'subtype', 'commitMessage', 'submitter', 'attachment'],
    autoFields: ['id', 'submittedAt', 'commitAreaKey', 'axis', 'status', 'source'],
    attachmentIds: [artifactRecord?.id].filter(Boolean),
    attachments: artifactRecord ? [artifactRecord] : [],
    summary: workSummary || commitMessage,
  };
}

function resolveAgentRef(ref, team = []) {
  if (!ref) return null;
  const normalized = String(ref).toLowerCase();
  return team.find((agent) => (
    String(agent.id || '').toLowerCase() === normalized
    || String(agent.name || '').toLowerCase() === normalized
  )) || null;
}

function managementSignalItems({ project = {}, agent = {}, state = {} } = {}) {
  const team = project.team || [];
  const managerIds = uniqueStrings([
    state.managerId,
    ...(state.peerManagerIds || []),
  ]);
  const managerRefs = new Set([
    ...managerIds,
    ...managerIds.map((id) => team.find((member) => member.id === id)?.name).filter(Boolean),
  ]);
  return (state.inbox || []).filter((item) => {
    if (item.status === 'addressed' || item.status === 'done' || item.respondedAt) return false;
    return ['management-check-in', 'peer-management-check-in', 'review-sweep', 'change-sync'].includes(item.source)
      || managerRefs.has(item.from)
      || /management check-in|peer-management|review sweep|plan updated/i.test(item.text || '');
  }).slice(0, 4);
}

function managementResponseTargets({ project = {}, state = {}, signals = [] } = {}) {
  const team = project.team || [];
  const signalManagers = signals
    .map((item) => resolveAgentRef(item.from, team)?.id)
    .filter(Boolean);
  return uniqueStrings([
    ...signalManagers,
    state.managerId,
    ...(state.peerManagerIds || []),
  ]).filter(Boolean);
}

function pendingSubmissionForReviewer({ project = {}, reviewer = {}, submissionId = null } = {}) {
  const reviewerId = String(reviewer.id || reviewer.agentId || '').trim();
  const reviewerName = String(reviewer.name || '').trim();
  const reviewerLooksLikeReviewer = /review|evidence|qa|critic|risk/i.test(`${reviewer.role || ''} ${reviewer.title || ''} ${reviewer.skill || ''}`);
  const reviewableStatuses = new Set(['pending-review', 'under-review', 'submitted']);
  const submissions = project.agentSubmissions || [];
  const candidates = submissionId
    ? submissions.filter((submission) => String(submission.id || '') === String(submissionId))
    : submissions;
  return candidates.find((submission) => {
    if (!submission?.id) return false;
    if (String(submission.agentId || '') === reviewerId) return false;
    const status = String(submission.reviewStatus || submission.status || 'pending-review');
    if (!reviewableStatuses.has(status)) return false;
    const requestedIds = uniqueStrings([
      submission.requestedReviewAgentId,
      submission.reviewerAgentId,
      submission.requestedReviewerAgentId,
    ].filter(Boolean)).map(String);
    const requestedNames = uniqueStrings([
      submission.requestedReviewAgentName,
      submission.reviewerAgentName,
      submission.requestedReviewerAgentName,
    ].filter(Boolean)).map(String);
    if (requestedIds.includes(reviewerId) || (reviewerName && requestedNames.includes(reviewerName))) return true;
    return !requestedIds.length && !requestedNames.length && reviewerLooksLikeReviewer;
  }) || null;
}

function pendingReviewResponseForAgent({ project = {}, agent = {}, state = {}, reviewId = null } = {}) {
  const agentId = String(agent.id || agent.agentId || '').trim();
  const reviews = project.submissionReviews || [];
  const submissions = project.agentSubmissions || [];
  const responseExists = (review = {}) => submissions.some((submission) => (
    String(submission.respondsToReviewId || '') === String(review.id || '')
    || String(submission.revisesSubmissionId || '') === String(review.submissionId || '')
    || (submission.supersedesSubmissionIds || []).map(String).includes(String(review.submissionId || ''))
  ));
  const reviewMatchesAgent = (review = {}) => String(review.submitterAgentId || '') === agentId
    || String(submissions.find((submission) => String(submission.id || '') === String(review.submissionId || ''))?.agentId || '') === agentId;
  const candidateObligations = (state.obligations || []).filter((obligation) => {
    if (['done', 'resolved', 'closed'].includes(obligation.status)) return false;
    if (obligation.source !== 'submission-review' && !obligation.reviewId && !obligation.submissionId) return false;
    if (reviewId && String(obligation.reviewId || '') !== String(reviewId)) return false;
    return true;
  });
  for (const obligation of candidateObligations) {
    const review = reviews.find((item) => (
      String(item.id || '') === String(obligation.reviewId || '')
      || (
        String(item.submissionId || '') === String(obligation.submissionId || '')
        && item.verdict === 'changes-requested'
      )
    ));
    if (!review || review.verdict !== 'changes-requested') continue;
    if (!reviewMatchesAgent(review) || responseExists(review)) continue;
    const submission = submissions.find((item) => String(item.id || '') === String(review.submissionId || '')) || null;
    return { review, submission, obligation };
  }
  const fallbackReview = reviews.find((review) => (
    (!reviewId || String(review.id || '') === String(reviewId))
    && review.verdict === 'changes-requested'
    && reviewMatchesAgent(review)
    && !responseExists(review)
  ));
  if (!fallbackReview) return null;
  return {
    review: fallbackReview,
    submission: submissions.find((item) => String(item.id || '') === String(fallbackReview.submissionId || '')) || null,
    obligation: null,
  };
}

function reviewerAgentIdForAutonomousWork(project = {}, agent = {}) {
  const team = project.team || [];
  const agentId = String(agent.id || agent.agentId || '');
  const governanceReviewerId = project.kickoffCharter?.governance?.reviewerId
    || project.initiation?.kickoffCharter?.governance?.reviewerId
    || project.governance?.reviewerId
    || null;
  if (governanceReviewerId && String(governanceReviewerId) !== agentId) return governanceReviewerId;
  const reviewer = team.find((member) => (
    String(member.id || '') !== agentId
    && /review|evidence|qa|critic|risk/i.test(`${member.role || ''} ${member.title || ''} ${member.skill || ''}`)
  ));
  if (reviewer?.id) return reviewer.id;
  return team.find((member) => String(member.id || '') !== agentId)?.id || null;
}

function buildAgentAutonomousStrategyDecision({
  project = {},
  agent = {},
  state = {},
  task = null,
  completed = false,
  managementSignals = [],
  now = nowIso(),
  trigger = 'agent-worker',
  cadence = 'agent-pulse',
  controls = {},
} = {}) {
  const timestamp = Date.parse(now) || Date.now();
  const pendingReviewResponse = pendingReviewResponseForAgent({
    project,
    agent,
    state,
    reviewId: controls.reviewResponseId,
  });
  const pendingReviewSubmission = pendingSubmissionForReviewer({
    project,
    reviewer: agent,
    submissionId: controls.reviewSubmissionId,
  });
  const openOwnedTasks = (project.tasks || []).filter((item) => taskBelongsToAgent(item, agent) && item.status !== 'done');
  const selectedReviewerAgentId = controls.workArtifactReviewerAgentId
    || controls.reviewResponseReviewerAgentId
    || reviewerAgentIdForAutonomousWork(project, agent);
  const selectedWorkArtifactType = resolveAgentWorkArtifactType({
    value: controls.workArtifactType,
    project,
    agent,
    task,
  });
  const explicitActions = [
    controls.submitWorkArtifact ? 'submit-work-artifact' : null,
    controls.reviewPendingSubmission ? 'review-pending-submission' : null,
    controls.respondToReviewObligation ? 'respond-to-review-obligation' : null,
  ].filter(Boolean);

  let selectedAction = 'monitor-project';
  let priority = 10;
  const rationale = [];
  const nextControls = {
    submitWorkArtifact: Boolean(controls.submitWorkArtifact),
    workArtifactType: selectedWorkArtifactType,
    workArtifactReviewStatus: controls.workArtifactReviewStatus || 'pending-review',
    workArtifactReviewerAgentId: controls.workArtifactReviewerAgentId || selectedReviewerAgentId,
    submitWorkArtifactOn: controls.submitWorkArtifactOn || 'completion',
    reviewPendingSubmission: Boolean(controls.reviewPendingSubmission),
    reviewSubmissionId: controls.reviewSubmissionId || null,
    agentReviewVerdict: controls.agentReviewVerdict || 'under-review',
    agentReviewComments: controls.agentReviewComments || '',
    agentReviewRequestedChanges: controls.agentReviewRequestedChanges || [],
    respondToReviewObligation: Boolean(controls.respondToReviewObligation),
    reviewResponseId: controls.reviewResponseId || null,
    reviewResponseArtifactType: normalizeAgentSubmissionArtifactType(controls.reviewResponseArtifactType || 'revision-note'),
    reviewResponseReviewerAgentId: controls.reviewResponseReviewerAgentId || selectedReviewerAgentId,
    recordEvidenceSearch: Boolean(controls.recordEvidenceSearch),
    evidenceSearchQuery: controls.evidenceSearchQuery || task?.text || '',
    evidenceSearchPurpose: controls.evidenceSearchPurpose || '',
    evidenceSearchSources: Array.isArray(controls.evidenceSearchSources) ? controls.evidenceSearchSources : [],
    evidenceSearchFindings: Array.isArray(controls.evidenceSearchFindings) ? controls.evidenceSearchFindings : [],
    evidenceSearchConfidence: controls.evidenceSearchConfidence || 'high',
  };

  const explicitReviewSubmissionRequested = Boolean(
    controls.reviewPendingSubmission
    && controls.reviewSubmissionId
    && pendingReviewSubmission?.id
  );
  if (explicitReviewSubmissionRequested) {
    selectedAction = 'review-pending-submission';
    priority = 90;
    rationale.push('Caller targeted a specific pending submission review, so that review takes priority over unrelated obligations.');
    nextControls.reviewPendingSubmission = true;
    nextControls.reviewSubmissionId = pendingReviewSubmission.id;
    nextControls.agentReviewVerdict = controls.agentReviewVerdict || 'auto';
    nextControls.agentReviewRequestedChanges = controls.agentReviewRequestedChanges || [];
    nextControls.submitWorkArtifact = false;
    nextControls.respondToReviewObligation = false;
  } else if (pendingReviewResponse?.review) {
    selectedAction = 'respond-to-review-obligation';
    priority = 95;
    rationale.push('Agent has an open changes-requested review obligation that should be closed before new work expands.');
    nextControls.respondToReviewObligation = true;
    nextControls.reviewResponseId = pendingReviewResponse.review.id;
    nextControls.reviewResponseArtifactType = normalizeAgentSubmissionArtifactType(controls.reviewResponseArtifactType || 'revision-note');
    nextControls.reviewResponseReviewerAgentId = controls.reviewResponseReviewerAgentId
      || pendingReviewResponse.review.reviewerAgentId
      || pendingReviewResponse.submission?.requestedReviewAgentId
      || selectedReviewerAgentId;
  } else if (pendingReviewSubmission?.id) {
    selectedAction = 'review-pending-submission';
    priority = 85;
    rationale.push('Agent can act as Reviewer for a pending teammate submission.');
    nextControls.reviewPendingSubmission = true;
    nextControls.reviewSubmissionId = pendingReviewSubmission.id;
    nextControls.agentReviewVerdict = controls.agentReviewVerdict || 'auto';
    nextControls.agentReviewRequestedChanges = controls.agentReviewRequestedChanges || [];
  } else if (task && completed) {
    selectedAction = 'complete-and-submit-owned-work';
    priority = 75;
    rationale.push('Owned task reaches completion in this pulse, so the work should be submitted as a Manager-visible node.');
    nextControls.submitWorkArtifact = true;
    nextControls.workArtifactType = selectedWorkArtifactType;
    nextControls.workArtifactReviewerAgentId = controls.workArtifactReviewerAgentId || selectedReviewerAgentId;
    nextControls.submitWorkArtifactOn = controls.submitWorkArtifactOn || 'completion';
    nextControls.recordEvidenceSearch = Boolean(controls.recordEvidenceSearch)
      || shouldAgentWorkerRecordEvidenceSearch({ task, workArtifactType: selectedWorkArtifactType });
    nextControls.evidenceSearchQuery = controls.evidenceSearchQuery || task?.text || '';
    nextControls.evidenceSearchPurpose = controls.evidenceSearchPurpose || `Collect evidence for ${task?.text || 'the completed Agent task'}.`;
  } else if (managementSignals.length) {
    selectedAction = 'answer-management-signal';
    priority = 65;
    rationale.push('Agent has management or peer-management signals that need an auditable response.');
  } else if (task) {
    selectedAction = 'continue-owned-work';
    priority = 55;
    rationale.push('Agent has an open owned task and should continue producing work evidence.');
  } else {
    rationale.push('No open owned task, review obligation, or pending review was found, so the Agent monitors the project lane.');
  }

  if (explicitActions.length) {
    rationale.push(`Caller supplied explicit controls: ${explicitActions.join(', ')}.`);
  }

  const enabledActions = [
    nextControls.respondToReviewObligation ? 'respond-to-review-obligation' : null,
    nextControls.reviewPendingSubmission ? 'review-pending-submission' : null,
    nextControls.submitWorkArtifact ? 'submit-work-artifact' : null,
    managementSignals.length ? 'answer-management-signal' : null,
    task ? 'work-owned-task' : 'monitor-project',
  ].filter(Boolean);

  return redactSensitiveObject({
    id: `agent_strategy_${agent.id || agent.agentId || 'agent'}_${timestamp}`,
    schemaVersion: 'agent-autonomous-strategy-decision/v1',
    projectId: project.id || null,
    agentId: agent.id || agent.agentId || null,
    agentName: agent.name || null,
    decidedAt: now,
    trigger,
    cadence,
    selectedAction,
    priority,
    enabledActions: uniqueStrings(enabledActions),
    rationale,
    nextStep: selectedAction === 'respond-to-review-obligation'
      ? 'Submit a linked revision response.'
      : selectedAction === 'review-pending-submission'
        ? 'Review the pending teammate submission.'
        : selectedAction === 'complete-and-submit-owned-work'
          ? 'Submit completed work as an Agent artifact node.'
          : selectedAction === 'continue-owned-work'
            ? 'Continue owned task work and publish progress proof.'
            : selectedAction === 'answer-management-signal'
              ? 'Answer management signals before continuing.'
              : 'Monitor project state for the next actionable obligation.',
    inputs: {
      openOwnedTaskCount: openOwnedTasks.length,
      taskId: task?.id || null,
      taskStatusBeforePulse: task?.status || null,
      completedThisPulse: Boolean(completed),
      managementSignalCount: managementSignals.length,
      pendingReviewResponseId: pendingReviewResponse?.review?.id || null,
      pendingReviewResponseSubmissionId: pendingReviewResponse?.submission?.id || null,
      pendingReviewSubmissionId: pendingReviewSubmission?.id || null,
      explicitActions,
    },
    controls: nextControls,
  });
}

function actionLabelForAgentStrategy(action = '') {
  return ({
    'respond-to-review-obligation': 'Respond to requested changes',
    'review-pending-submission': 'Review pending teammate submission',
    'complete-and-submit-owned-work': 'Submit completed owned work',
    'answer-management-signal': 'Answer management signal',
    'continue-owned-work': 'Continue owned work',
    'monitor-project': 'Monitor project lane',
  }[action] || action || 'Agent autonomous action');
}

function buildAgentAutonomousInitiativeRow({
  projectId = null,
  queueRow = {},
  index = 0,
} = {}) {
  const requestBody = queueRow.requestBodyTemplate || {};
  const controls = queueRow.strategyDecision?.controls || {};
  const selectedAction = queueRow.selectedAction || queueRow.strategyDecision?.selectedAction || 'monitor-project';
  const artifactType = normalizeAgentSubmissionArtifactType(
    requestBody.workArtifactType
    || requestBody.agentWorkArtifactType
    || controls.workArtifactType
    || requestBody.reviewResponseArtifactType
    || controls.reviewResponseArtifactType
    || 'progress-brief',
  );
  const proofIds = uniqueStrings(queueRow.proofIds || []);
  const timelineLogIds = uniqueStrings(queueRow.timelineLogIds || []);
  const eventIds = uniqueStrings(queueRow.eventIds || []);
  const intent = queueRow.nextStep
    || queueRow.strategyDecision?.nextStep
    || actionLabelForAgentStrategy(selectedAction);
  const row = {
    id: `agent-autonomous-initiative-${queueRow.agentId || index}`,
    schemaVersion: 'agent-autonomous-initiative/v1',
    projectId,
    queueRowId: queueRow.id || null,
    agentId: queueRow.agentId || null,
    name: queueRow.name || queueRow.agentName || null,
    role: queueRow.role || '',
    status: queueRow.canRun ? 'ready-to-run' : queueRow.status || 'monitoring',
    canRun: Boolean(queueRow.canRun),
    due: Boolean(queueRow.due),
    selectedAction,
    actionLabel: queueRow.actionLabel || actionLabelForAgentStrategy(selectedAction),
    intent,
    rationale: uniqueStrings(queueRow.rationale || queueRow.strategyDecision?.rationale || []).slice(0, 5),
    taskId: queueRow.taskId || null,
    taskText: queueRow.taskText || null,
    artifactType,
    targetReviewSubmissionId: requestBody.reviewSubmissionId || queueRow.pendingReviewSubmissionId || null,
    targetReviewResponseId: requestBody.reviewResponseId || queueRow.pendingReviewResponseId || null,
    reviewerAgentId: requestBody.workArtifactReviewerAgentId
      || requestBody.agentWorkArtifactReviewerAgentId
      || requestBody.reviewResponseReviewerAgentId
      || controls.workArtifactReviewerAgentId
      || controls.reviewResponseReviewerAgentId
      || null,
    evidenceSearchPlanned: Boolean(requestBody.recordEvidenceSearch || controls.recordEvidenceSearch || artifactType === 'evidence-packet'),
    providerEvidenceSearchPlanned: Boolean(requestBody.useProviderEvidenceSearch || controls.useProviderEvidenceSearch),
    runApiPath: queueRow.runApiPath || null,
    agentWorkCycleApiPath: queueRow.agentWorkCycleApiPath || null,
    strategyDecisionId: queueRow.strategyDecision?.id || null,
    priority: queueRow.managementPriority || queueRow.strategyDecision?.priority || 0,
    proofIds,
    timelineLogIds,
    eventIds,
  };
  return redactSensitiveObject({
    ...row,
    checksum: persistenceChecksum(row),
  });
}

function buildAutonomousActionDecision({
  projectId = null,
  queueRow = {},
  requestBody = {},
  now = nowIso(),
  force = false,
  providerPreflight = null,
  source = 'agent-autonomous-action-queue',
} = {}) {
  const strategyDecision = queueRow.strategyDecision || null;
  const selectedAction = queueRow.selectedAction || strategyDecision?.selectedAction || 'monitor-project';
  const artifactType = normalizeAgentSubmissionArtifactType(
    requestBody.workArtifactType
    || requestBody.agentWorkArtifactType
    || requestBody.reviewResponseArtifactType
    || strategyDecision?.controls?.workArtifactType
    || strategyDecision?.controls?.reviewResponseArtifactType
    || 'progress-brief',
  );
  const canRun = Boolean(queueRow.canRun || force);
  const action = !canRun
    ? 'blocked'
    : force && !queueRow.canRun
      ? 'force-run'
      : selectedAction === 'monitor-project'
        ? 'monitor'
        : 'run-now';
  const reasons = uniqueStrings([
    ...(queueRow.rationale || strategyDecision?.rationale || []),
    force && !queueRow.canRun ? 'Caller forced execution despite queue row not being marked runnable.' : null,
    !canRun ? 'Queue row is not runnable.' : null,
    providerPreflight?.schemaVersion === 'autonomous-provider-preflight/v1'
      ? `Provider preflight action: ${providerPreflight.action}.`
      : null,
  ].filter(Boolean));
  const targetIds = uniqueStrings([
    queueRow.taskId,
    requestBody.taskId,
    requestBody.reviewSubmissionId,
    requestBody.reviewResponseId,
    strategyDecision?.inputs?.taskId,
    strategyDecision?.inputs?.pendingReviewSubmissionId,
    strategyDecision?.inputs?.pendingReviewResponseId,
  ].filter(Boolean));
  const decision = redactSensitiveObject({
    id: `autonomous_action_decision_${projectId || 'project'}_${queueRow.agentId || queueRow.id || 'agent'}_${Date.parse(now) || Date.now()}`,
    schemaVersion: 'autonomous-action-decision/v1',
    projectId,
    source,
    decidedAt: now,
    agentId: queueRow.agentId || null,
    agentName: queueRow.name || queueRow.agentName || null,
    role: queueRow.role || null,
    queueRowId: queueRow.id || null,
    queueRowChecksum: queueRow.checksum || null,
    action,
    canRun,
    forced: Boolean(force),
    selectedAction,
    actionLabel: queueRow.actionLabel || actionLabelForAgentStrategy(selectedAction),
    nextStep: queueRow.nextStep || strategyDecision?.nextStep || null,
    priority: queueRow.managementPriority || strategyDecision?.priority || 0,
    rationale: reasons.slice(0, 8),
    strategyDecisionId: strategyDecision?.id || queueRow.strategyDecisionId || null,
    strategyDecision,
    initiative: queueRow.initiative || null,
    initiativeId: queueRow.initiativeId || queueRow.initiative?.id || null,
    initiativeArtifactType: queueRow.initiativeArtifactType || queueRow.initiative?.artifactType || artifactType,
    artifactType,
    taskId: queueRow.taskId || requestBody.taskId || strategyDecision?.inputs?.taskId || null,
    targetIds,
    providerEvidenceRequested: Boolean(requestBody.useProviderEvidenceSearch || requestBody.requireProviderEvidenceSearch),
    providerPreflight: providerPreflight ? redactSensitiveObject(providerPreflight) : null,
    providerPreflightChecksum: providerPreflight?.checksum || null,
    providerPreflightAction: providerPreflight?.action || null,
    evidenceSearchPlanned: Boolean(requestBody.recordEvidenceSearch || artifactType === 'evidence-packet'),
    reviewPlanned: Boolean(requestBody.reviewPendingSubmission || requestBody.reviewSubmissionId),
    revisionPlanned: Boolean(requestBody.respondToReviewObligation || requestBody.reviewResponseId),
    submissionPlanned: Boolean(requestBody.submitWorkArtifact || requestBody.submitAgentWorkArtifacts),
    proofIds: uniqueStrings([
      ...(queueRow.proofIds || []),
      strategyDecision?.id,
      queueRow.initiativeId,
      queueRow.initiative?.id,
    ].filter(Boolean)),
    timelineLogIds: uniqueStrings(queueRow.timelineLogIds || []),
    eventIds: uniqueStrings(queueRow.eventIds || []),
    backendRoutes: {
      agentAutonomousActionQueue: projectId ? `/projects/${projectId}/agent-autonomous-action-queue` : null,
      run: queueRow.runApiPath || null,
      delegatedWorkCycle: queueRow.agentWorkCycleApiPath || null,
      managerFlowGraph: projectId ? `/projects/${projectId}/manager-flow-graph` : null,
      readinessProofMap: projectId ? `/projects/${projectId}/readiness-proof-map` : null,
    },
    readyForProduction: false,
  });
  decision.checksum = persistenceChecksum({
    projectId,
    source,
    agentId: decision.agentId,
    queueRowId: decision.queueRowId,
    queueRowChecksum: decision.queueRowChecksum,
    action,
    selectedAction,
    strategyDecisionId: decision.strategyDecisionId,
    initiativeId: decision.initiativeId,
    artifactType,
    targetIds,
    providerPreflightChecksum: decision.providerPreflightChecksum,
    proofIds: decision.proofIds,
  });
  return decision;
}

function buildAgentAutonomousActionQueue({
  project = {},
  now = nowIso(),
  intervalMs,
  providerEvidenceSearchEnabled = false,
} = {}) {
  const projectId = project.id || null;
  const rows = (project.team || []).filter((agent) => agent?.id).map((agent) => {
    const state = project.agentStates?.[agent.id] || {};
    const task = openAgentTask(project, agent);
    const nextPulseCount = task ? (task.workPulseCount || 0) + 1 : 0;
    const completedNextPulse = Boolean(task && nextPulseCount >= 2);
    const managementSignals = managementSignalItems({ project, agent, state });
    const schedule = evaluateAgentWorkSchedule({
      project,
      agentId: agent.id,
      now,
      intervalMs,
    });
    const strategyDecision = buildAgentAutonomousStrategyDecision({
      project,
      agent,
      state,
      task,
      completed: completedNextPulse,
      managementSignals,
      now,
      trigger: 'agent-autonomous-action-queue',
      cadence: 'agent-autonomous-action',
      controls: {
        submitWorkArtifact: true,
        workArtifactType: 'auto',
        workArtifactReviewStatus: 'pending-review',
        workArtifactReviewerAgentId: reviewerAgentIdForAutonomousWork(project, agent),
        reviewPendingSubmission: true,
        agentReviewVerdict: 'auto',
        respondToReviewObligation: true,
        reviewResponseArtifactType: 'revision-note',
        reviewResponseReviewerAgentId: reviewerAgentIdForAutonomousWork(project, agent),
      },
    });
    const latestWorker = (project.agentWorkerLedger || []).find((record) => record.agentId === agent.id) || null;
    const latestEventIds = uniqueStrings((project.eventLedger || [])
      .filter((event) => event.entityIds?.agentId === agent.id || event.entityIds?.targetAgentId === agent.id)
      .map((event) => event.id))
      .slice(0, 8);
    const proofIds = uniqueStrings([
      latestWorker?.messageId,
      ...(strategyDecision.inputs?.pendingReviewSubmissionId ? [strategyDecision.inputs.pendingReviewSubmissionId] : []),
      ...(strategyDecision.inputs?.pendingReviewResponseId ? [strategyDecision.inputs.pendingReviewResponseId] : []),
    ].filter(Boolean));
    const timelineLogIds = uniqueStrings([
      latestWorker?.logId,
      ...(latestWorker?.timelineLogIds || []),
    ].filter(Boolean));
    const canRun = Boolean(projectId && strategyDecision.selectedAction !== 'monitor-project');
    const plannedArtifactType = strategyDecision.controls?.workArtifactType || 'progress-brief';
    const plannedEvidenceSearch = Boolean(
      strategyDecision.controls?.recordEvidenceSearch
      || normalizeAgentSubmissionArtifactType(plannedArtifactType) === 'evidence-packet'
    );
    const useProviderEvidenceSearch = Boolean(providerEvidenceSearchEnabled && plannedEvidenceSearch);
    const requestBodyTemplate = {
      useAutonomousStrategy: true,
      submitWorkArtifact: true,
      workArtifactType: plannedArtifactType,
      workArtifactReviewerAgentId: strategyDecision.controls?.workArtifactReviewerAgentId || null,
      recordEvidenceSearch: Boolean(strategyDecision.controls?.recordEvidenceSearch),
      evidenceSearchQuery: strategyDecision.controls?.evidenceSearchQuery || null,
      evidenceSearchPurpose: strategyDecision.controls?.evidenceSearchPurpose || null,
      ...(useProviderEvidenceSearch ? {
        useProviderEvidenceSearch: true,
        requireProviderEvidenceSearch: false,
      } : {}),
      reviewPendingSubmission: true,
      reviewSubmissionId: strategyDecision.controls?.reviewSubmissionId || null,
      agentReviewVerdict: strategyDecision.controls?.agentReviewVerdict || 'auto',
      agentReviewRequestedChanges: strategyDecision.controls?.agentReviewRequestedChanges || [],
      respondToReviewObligation: true,
      reviewResponseId: strategyDecision.controls?.reviewResponseId || null,
      reviewResponseArtifactType: strategyDecision.controls?.reviewResponseArtifactType || 'revision-note',
      reviewResponseReviewerAgentId: strategyDecision.controls?.reviewResponseReviewerAgentId || null,
      trigger: 'agent-autonomous-action-queue-run',
      cadence: 'agent-autonomous-action',
      includeReadModels: false,
    };
    const checksum = persistenceChecksum({
      schemaVersion: 'agent-autonomous-action-queue-row/v1',
      projectId,
      agentId: agent.id,
      selectedAction: strategyDecision.selectedAction,
      requestBodyTemplate,
      providerEvidenceSearchEnabled: Boolean(providerEvidenceSearchEnabled),
      proofIds,
      timelineLogIds,
      latestEventIds,
    });
    const queueRowId = `agent-autonomous-action-${agent.id}`;
    const initiative = buildAgentAutonomousInitiativeRow({
      projectId,
      queueRow: {
        id: queueRowId,
        agentId: agent.id,
        name: agent.name,
        role: agent.role || agent.title || '',
        status: canRun ? schedule.due ? 'ready' : 'scheduled' : 'monitoring',
        canRun,
        due: Boolean(schedule.due),
        managementPriority: schedule.managementPriority || strategyDecision.priority || 0,
        selectedAction: strategyDecision.selectedAction,
        actionLabel: actionLabelForAgentStrategy(strategyDecision.selectedAction),
        nextStep: strategyDecision.nextStep,
        rationale: strategyDecision.rationale || [],
        strategyDecision,
        taskId: task?.id || null,
        taskText: task?.text || null,
        pendingReviewSubmissionId: strategyDecision.inputs?.pendingReviewSubmissionId || null,
        pendingReviewResponseId: strategyDecision.inputs?.pendingReviewResponseId || null,
        runApiPath: projectId ? `/projects/${projectId}/agent-autonomous-action-queue/${encodeURIComponent(agent.id)}/run` : null,
        agentWorkCycleApiPath: projectId ? `/projects/${projectId}/agents/${encodeURIComponent(agent.id)}/work-cycle` : null,
        requestBodyTemplate,
        providerEvidenceSearchPlanned: useProviderEvidenceSearch,
        proofIds,
        timelineLogIds,
        eventIds: latestEventIds,
      },
    });
    return redactSensitiveObject({
      id: queueRowId,
      schemaVersion: 'agent-autonomous-action-queue-row/v1',
      projectId,
      agentId: agent.id,
      name: agent.name,
      role: agent.role || agent.title || '',
      status: canRun ? schedule.due ? 'ready' : 'scheduled' : 'monitoring',
      canRun,
      routeResolved: Boolean(projectId),
      due: Boolean(schedule.due),
      dueAt: schedule.dueAt || null,
      nextRunAt: schedule.nextRunAt || state.nextAgentRunAt || latestWorker?.nextRunAt || null,
      managementPriority: schedule.managementPriority || strategyDecision.priority || 0,
      managementReasons: schedule.managementReasons || [],
      selectedAction: strategyDecision.selectedAction,
      actionLabel: actionLabelForAgentStrategy(strategyDecision.selectedAction),
      nextStep: strategyDecision.nextStep,
      rationale: strategyDecision.rationale || [],
      strategyDecision,
      taskId: task?.id || null,
      taskText: task?.text || null,
      taskWillCompleteOnRun: completedNextPulse,
      pendingReviewSubmissionId: strategyDecision.inputs?.pendingReviewSubmissionId || null,
      pendingReviewResponseId: strategyDecision.inputs?.pendingReviewResponseId || null,
      managementSignalCount: strategyDecision.inputs?.managementSignalCount || 0,
      runApiPath: projectId ? `/projects/${projectId}/agent-autonomous-action-queue/${encodeURIComponent(agent.id)}/run` : null,
      agentWorkCycleApiPath: projectId ? `/projects/${projectId}/agents/${encodeURIComponent(agent.id)}/work-cycle` : null,
      dueWorkerApiPath: '/workers/agents/due',
      method: 'POST',
      requestBodyTemplate,
      initiative,
      initiativeId: initiative.id,
      initiativeArtifactType: initiative.artifactType,
      initiativeIntent: initiative.intent,
      providerEvidenceSearchPlanned: useProviderEvidenceSearch,
      proofIds,
      timelineLogIds,
      eventIds: latestEventIds,
      checksum,
    });
  }).sort((a, b) => (
    Number(b.canRun) - Number(a.canRun)
    || (b.managementPriority || 0) - (a.managementPriority || 0)
    || String(a.nextRunAt || '').localeCompare(String(b.nextRunAt || ''))
    || String(a.agentId || '').localeCompare(String(b.agentId || ''))
  ));
  const readyRows = rows.filter((row) => row.canRun);
  const proofIds = uniqueStrings(rows.flatMap((row) => row.proofIds || []));
  const timelineLogIds = uniqueStrings(rows.flatMap((row) => row.timelineLogIds || []));
  const eventIds = uniqueStrings(rows.flatMap((row) => row.eventIds || []));
  const checksum = persistenceChecksum({
    schemaVersion: 'agent-autonomous-action-queue/v1',
    projectId,
    rows: rows.map((row) => [row.agentId, row.selectedAction, row.canRun, row.nextRunAt]),
    providerEvidenceSearchRowCount: rows.filter((row) => row.providerEvidenceSearchPlanned).length,
    proofIds,
    timelineLogIds,
    eventIds,
  });
  return redactSensitiveObject({
    projectId,
    generatedAt: now,
    schemaVersion: 'agent-autonomous-action-queue/v1',
    status: readyRows.length ? 'agent-actions-ready' : rows.length ? 'agent-actions-monitoring' : 'no-agents',
    readyCount: readyRows.length,
    count: rows.length,
    dueCount: rows.filter((row) => row.due).length,
    monitoringCount: rows.filter((row) => row.selectedAction === 'monitor-project').length,
    nextAction: readyRows[0] || rows[0] || null,
    rows,
    proofIds,
    timelineLogIds,
    eventIds,
    backendRoutes: {
      agentAutonomousActionQueue: projectId ? `/projects/${projectId}/agent-autonomous-action-queue` : null,
      agentAutonomousActionRunTemplate: projectId ? `/projects/${projectId}/agent-autonomous-action-queue/:agentId/run` : null,
      agentsDue: '/workers/agents/due',
      managerDashboard: projectId ? `/projects/${projectId}/manager-dashboard` : null,
      managerFlowGraph: projectId ? `/projects/${projectId}/manager-flow-graph` : null,
      readinessProofMap: projectId ? `/projects/${projectId}/readiness-proof-map` : null,
    },
    summary: {
      actionCounts: rows.reduce((acc, row) => ({
        ...acc,
        [row.selectedAction]: (acc[row.selectedAction] || 0) + 1,
      }), {}),
      initiativeCount: rows.filter((row) => row.initiative?.schemaVersion === 'agent-autonomous-initiative/v1').length,
      readyInitiativeCount: rows.filter((row) => row.initiative?.canRun).length,
      initiativeArtifactTypes: uniqueStrings(rows.map((row) => row.initiative?.artifactType).filter(Boolean)),
      providerEvidenceSearchRowCount: rows.filter((row) => row.providerEvidenceSearchPlanned).length,
      readyCount: readyRows.length,
      dueCount: rows.filter((row) => row.due).length,
      proofIdCount: proofIds.length,
      timelineLogIdCount: timelineLogIds.length,
      eventIdCount: eventIds.length,
      checksum,
    },
    checksum,
  });
}

function automaticReviewVerdictForSubmission(submission = {}) {
  if (
    submission.respondsToReviewId
    || submission.revisesSubmissionId
    || submission.artifactType === 'revision-note'
    || submission.artifactType === 'final-deliverable'
    || submission.status === 'final'
  ) {
    return 'accepted';
  }
  return 'changes-requested';
}

export function evaluateAgentWorkSchedule({
  project = {},
  agentId,
  now = nowIso(),
  intervalMs,
  forceDue = false,
  forceReason = 'agent-forced-sweep',
} = {}) {
  const team = project.team || [];
  const agent = team.find((member) => member.id === agentId || member.name === agentId);
  if (!agent) {
    return {
      due: false,
      reason: 'agent-not-found',
      agentId,
      nextRunAt: null,
    };
  }
  if (project.autonomy?.enabled === false || project.agentAutonomy?.enabled === false) {
    return {
      due: false,
      reason: 'agent-autonomy-disabled',
      agentId: agent.id,
      nextRunAt: null,
    };
  }

  const state = project.agentStates?.[agent.id] || {};
  const management = agentManagementPriority({ project, agent, state });
  const cadenceMs = agentWorkIntervalMs(project, state, intervalMs);
  const schedule = evaluateLocalIntervalSchedule({
    lane: 'agent', now, intervalMs: cadenceMs,
    lastCompletedAt: state.lastAgentRunAt || null, storedNextAt: state.nextAgentRunAt || null,
    enabled: true, forceDue,
    reasons: {
      forced: forceReason, first: 'agent-cadence-due', due: 'agent-cadence-due', waiting: 'agent-cadence-waiting',
      clockRegression: 'agent-clock-regression-recovery', missed: 'agent-missed-cadence-recovery',
    },
  });

  return {
    ...schedule,
    agentId: agent.id,
    cadenceMs,
    forced: Boolean(forceDue),
    managementPriority: management.score,
    managementReasons: management.reasons,
    management,
  };
}

function normalizeWorkerKind(workerKind = '') {
  const value = String(workerKind || '').toLowerCase();
  if (value === 'agent-work' || value === 'agent-worker') return 'agent-worker';
  if (value === 'project-scheduler') return 'project-scheduler';
  if (value === 'project-autonomous' || value === 'autonomous-cycle') return 'project-autonomous';
  if (value === 'autopilot' || value === 'autopilot-session' || value === 'autonomous-run-control-session') return 'autopilot-session';
  return value || 'worker';
}

function workerQueueKind(workerKind = '') {
  const normalized = normalizeWorkerKind(workerKind);
  if (normalized === 'agent-worker') return 'agent-work';
  if (normalized === 'project-scheduler') return 'project-autonomous';
  return normalized;
}

function workerRunApiPath(workerKind = '') {
  const normalized = normalizeWorkerKind(workerKind);
  if (normalized === 'agent-worker') return '/workers/agents/due';
  if (normalized === 'autopilot-session') return '/workers/autopilot/due';
  return '/workers/autonomous/due';
}

function workerDirectRunApiPath({ workerKind = '', projectId = '', agentId = '', sessionId = '' } = {}) {
  const encodedProjectId = encodeURIComponent(projectId || '');
  const normalized = normalizeWorkerKind(workerKind);
  if (normalized === 'agent-worker') {
    return `/projects/${encodedProjectId}/agents/${encodeURIComponent(agentId || '')}/work-cycle`;
  }
  if (normalized === 'autopilot-session') {
    return `/projects/${encodedProjectId}/autonomous-run-control/sessions/${encodeURIComponent(sessionId || '')}/tick`;
  }
  return `/projects/${encodedProjectId}/autonomous-cycle`;
}

function workerRunReason(run = {}) {
  return run.queueReason || run.reason || run.schedulerReason || run.trigger || null;
}

function buildWorkerIdempotencyKey({
  workerKind = '',
  projectId = '',
  agentId = null,
  sessionId = null,
  dueAt = null,
  reason = null,
} = {}) {
  const queueKind = workerQueueKind(workerKind);
  const payload = {
    workerKind: queueKind,
    projectId,
    dueAt,
  };
  if (agentId) payload.agentId = agentId;
  if (sessionId) payload.sessionId = sessionId;
  if (queueKind === 'project-autonomous') payload.trigger = reason;
  else payload.reason = reason;
  return persistenceChecksum(payload);
}

function workerExecutionSucceeded(run = {}) {
  const explicitStatus = String(
    run.executionStatus
    || run.executionReceipt?.status
    || run.workerStatus
    || run.runStatus
    || ''
  ).toLowerCase();
  if (/dead|fail|error|timeout|exception/.test(explicitStatus)) return false;
  if (/success|succeed|complete|ack/.test(explicitStatus)) return true;

  const businessStatus = String(run.status || '').toLowerCase();
  if (/dead|fail|error|timeout|exception/.test(businessStatus)) return false;
  return true;
}

function addSecondsIso(value, seconds = 0) {
  const base = safeDateMs(value, Date.now());
  return new Date(base + (Number(seconds) || 0) * 1000).toISOString();
}

function buildWorkerRetryState({
  status = 'succeeded',
  attemptCount = 1,
  now = nowIso(),
  existing = null,
} = {}) {
  if (existing?.schemaVersion === 'worker-retry-state/v1') return existing;
  const resolvedAttemptCount = Math.max(0, Number(attemptCount) || 0);
  const failed = !['succeeded', 'queued', 'waiting', 'deferred'].includes(String(status || '').toLowerCase());
  const retryable = Boolean(failed && resolvedAttemptCount > 0 && resolvedAttemptCount < WORKER_QUEUE_MAX_ATTEMPTS);
  const backoffSeconds = WORKER_QUEUE_RETRY_BACKOFF_SECONDS[Math.min(
    Math.max(resolvedAttemptCount - 1, 0),
    WORKER_QUEUE_RETRY_BACKOFF_SECONDS.length - 1,
  )] || WORKER_QUEUE_RETRY_BACKOFF_SECONDS[0];
  return {
    schemaVersion: 'worker-retry-state/v1',
    attemptCount: resolvedAttemptCount,
    maxAttempts: WORKER_QUEUE_MAX_ATTEMPTS,
    backoffSeconds: WORKER_QUEUE_RETRY_BACKOFF_SECONDS,
    retryable,
    nextRetryAt: retryable ? addSecondsIso(now, backoffSeconds) : null,
    deadLettered: Boolean(failed && resolvedAttemptCount >= WORKER_QUEUE_MAX_ATTEMPTS),
  };
}

function buildQueuedWorkerControlFields({ idempotencyKey = '', leaseKey = '', status = 'queued' } = {}) {
  return {
    attemptCount: 0,
    maxAttempts: WORKER_QUEUE_MAX_ATTEMPTS,
    executionReceiptExpected: true,
    leaseSeconds: WORKER_QUEUE_RECOMMENDED_LEASE_SECONDS,
    retry: buildWorkerRetryState({ status, attemptCount: 0 }),
    deadLetter: null,
    recovery: {
      rerunByIdempotencyKey: true,
      idempotencyKey,
      leaseKey,
      deadLetterAfterAttempts: WORKER_QUEUE_MAX_ATTEMPTS,
    },
  };
}

function buildWorkerRunControlFields(run = {}, {
  projectId = run.projectId,
  workerKind = run.workerKind,
  now = nowIso(),
} = {}) {
  const resolvedWorkerKind = normalizeWorkerKind(workerKind || run.workerKind);
  const resolvedProjectId = run.projectId || projectId || null;
  const resolvedSessionId = run.sessionId || run.autopilotSessionId || null;
  const reason = workerRunReason(run);
  const ranAt = run.ranAt || run.time || run.startedAt || run.completedAt || now;
  const dueAt = run.dueAt || ranAt;
  const idempotencyKey = run.idempotencyKey || buildWorkerIdempotencyKey({
    workerKind: resolvedWorkerKind,
    projectId: resolvedProjectId,
    agentId: run.agentId || null,
    sessionId: resolvedSessionId,
    dueAt,
    reason,
  });
  const leaseKey = run.leaseKey || `lease:${idempotencyKey}`;
  const executionStatus = workerExecutionSucceeded(run) ? 'succeeded' : 'failed';
  const attemptCount = Math.max(1, Number(run.retry?.attemptCount || run.attemptCount || 1) || 1);
  const retry = buildWorkerRetryState({
    status: executionStatus,
    attemptCount,
    now: ranAt,
    existing: run.retry,
  });
  const messageIds = uniqueStrings([
    run.messageId,
    ...(run.messageIds || []),
  ].filter(Boolean));
  const timelineLogIds = uniqueStrings([
    run.logId,
    ...(run.timelineLogIds || []),
  ].filter(Boolean));
  const receiptPayload = {
    runId: run.id || null,
    projectId: resolvedProjectId,
    workerKind: resolvedWorkerKind,
    agentId: run.agentId || null,
    sessionId: resolvedSessionId,
    taskId: run.taskId || null,
    status: executionStatus,
    idempotencyKey,
    leaseKey,
    dueAt,
    ranAt,
    completedAt: run.completedAt || ranAt,
    messageIds,
    timelineLogIds,
  };
  const executionReceipt = run.executionReceipt?.schemaVersion === 'worker-execution-receipt/v1'
    ? run.executionReceipt
    : {
      schemaVersion: 'worker-execution-receipt/v1',
      runId: run.id || null,
      projectId: resolvedProjectId,
      workerKind: resolvedWorkerKind,
      agentId: run.agentId || null,
      sessionId: resolvedSessionId,
      status: executionStatus,
      acked: executionStatus === 'succeeded',
      idempotencyKey,
      leaseKey,
      receivedAt: run.completedAt || ranAt,
      messageIds,
      timelineLogIds,
      receiptChecksum: persistenceChecksum(receiptPayload),
    };
  const deadLetter = run.deadLetter || (retry.deadLettered ? {
    schemaVersion: 'worker-dead-letter/v1',
    id: `dead_${idempotencyKey}`,
    runId: run.id || null,
    projectId: resolvedProjectId,
    workerKind: resolvedWorkerKind,
    agentId: run.agentId || null,
    sessionId: resolvedSessionId,
    status: 'dead-lettered',
    reason: reason || 'worker-failed-after-retries',
    attemptCount: retry.attemptCount,
    maxAttempts: retry.maxAttempts,
    queuedAt: run.completedAt || ranAt,
    recoveryApiPath: workerRunApiPath(resolvedWorkerKind),
    directRecoveryApiPath: workerDirectRunApiPath({
      workerKind: resolvedWorkerKind,
      projectId: resolvedProjectId,
      agentId: run.agentId || null,
      sessionId: resolvedSessionId,
    }),
    idempotencyKey,
    leaseKey,
  } : null);

  return {
    workerKind: resolvedWorkerKind,
    projectId: resolvedProjectId,
    sessionId: resolvedSessionId,
    idempotencyKey,
    leaseKey,
    executionStatus,
    attemptCount,
    maxAttempts: WORKER_QUEUE_MAX_ATTEMPTS,
    retry,
    executionReceipt,
    deadLetter,
  };
}

function withWorkerRunControlFields(run = {}, options = {}) {
  return {
    ...run,
    ...buildWorkerRunControlFields(run, options),
  };
}

function workerRunsForProject(project = {}) {
  const projectId = project.id || null;
  const dispositionsByDeadLetterId = new Map();
  (project.localDeadLetterDispositionLedger || []).forEach((row) => {
    if (row?.deadLetterId && !dispositionsByDeadLetterId.has(row.deadLetterId)) {
      dispositionsByDeadLetterId.set(row.deadLetterId, row);
    }
  });
  const applyDisposition = (run) => {
    const disposition = run.deadLetter?.id ? dispositionsByDeadLetterId.get(run.deadLetter.id) : null;
    if (!disposition) return run;
    return {
      ...run,
      deadLetter: {
        ...run.deadLetter,
        status: disposition.status,
        disposition,
      },
    };
  };
  return [
    ...(project.autonomousLedger || []).map((run) => withWorkerRunControlFields(run, { projectId, workerKind: 'project-autonomous' })),
    ...(project.autonomousSchedulerLedger || []).map((run) => withWorkerRunControlFields(run, { projectId, workerKind: 'project-scheduler' })),
    ...(project.agentWorkerLedger || []).map((run) => withWorkerRunControlFields(run, { projectId, workerKind: 'agent-worker' })),
    ...(project.autonomousRunControlSessionTickLedger || []).map((run) => withWorkerRunControlFields(run, { projectId, workerKind: 'autopilot-session' })),
  ].map(applyDisposition);
}

function verifyLocalDeadLetterDisposition(row = {}) {
  const { checksum, ...base } = row;
  return Boolean(checksum) && (checksum === durableTaskQueueChecksum(base) || checksum === persistenceChecksum(base));
}

function projectDeadLetterFacts(project = {}) {
  const dispositions = project.localDeadLetterDispositionLedger || [];
  if (dispositions.some((row) => !verifyLocalDeadLetterDisposition(row))) {
    throw new Error('local-dead-letter-disposition-integrity-invalid');
  }
  const dispositionById = new Map(dispositions.map((row) => [row.deadLetterId, row]));
  const durable = (project.localDurableTaskQueue || [])
    .filter((job) => job.status === 'dead-lettered')
    .map((job) => {
      const id = `dead_durable_${job.id}`;
      const disposition = dispositionById.get(id) || null;
      return {
        schemaVersion: 'worker-dead-letter/v1',
        id,
        projectId: job.projectId,
        workerKind: job.workerKind,
        agentId: job.agentId || null,
        sessionId: job.sessionId || null,
        status: disposition?.status || 'dead-lettered',
        sourceKind: 'durable-task',
        sourceJobId: job.id,
        sourceChecksum: job.checksum,
        queuedAt: job.updatedAt || job.createdAt,
        attemptCount: job.attemptCount,
        maxAttempts: job.maxAttempts,
        failureCodeHash: job.failureCodeHash || null,
        idempotencyKeyHash: durableTaskQueueChecksum(job.idempotencyKey),
        traceId: job.traceId || null,
        disposition,
        storesRequestBody: false,
      };
    });
  const legacy = workerRunsForProject(project)
    .filter((run) => run.deadLetter?.schemaVersion === 'worker-dead-letter/v1')
    .map((run) => {
      const { disposition: _existingDisposition, ...base } = run.deadLetter;
      const immutableBase = { ...base, status: 'dead-lettered' };
      const sourceChecksum = durableTaskQueueChecksum(immutableBase);
      const disposition = dispositionById.get(base.id) || null;
      return {
        ...immutableBase,
        status: disposition?.status || base.status,
        sourceKind: 'legacy-worker-run',
        sourceJobId: null,
        sourceChecksum,
        disposition,
        storesRequestBody: false,
      };
    });
  return [...durable, ...legacy];
}

function attachWorkerRunControlsToProject(project = {}) {
  const projectId = project.id || null;
  return {
    ...project,
    autonomousLedger: (project.autonomousLedger || []).map((run) => withWorkerRunControlFields(run, { projectId, workerKind: 'project-autonomous' })),
    autonomousSchedulerLedger: (project.autonomousSchedulerLedger || []).map((run) => withWorkerRunControlFields(run, { projectId, workerKind: 'project-scheduler' })),
    agentWorkerLedger: (project.agentWorkerLedger || []).map((run) => withWorkerRunControlFields(run, { projectId, workerKind: 'agent-worker' })),
    autonomousRunControlSessionTickLedger: (project.autonomousRunControlSessionTickLedger || []).map((run) => withWorkerRunControlFields(run, { projectId, workerKind: 'autopilot-session' })),
  };
}

export function hydrateAgentProject(project = {}) {
  return attachWorkerRunControlsToProject(backfillProjectEventLedger(project));
}

function projectEventSnapshot(project = {}) {
  return {
    schemaVersion: 'local-project-event-snapshot/v1',
    projectId: project.id || null,
    eventLedger: structuredClone(project.eventLedger || []),
    eventLedgerChainVersion: project.eventLedgerChainVersion || 0,
    eventLedgerPreviousHash: project.eventLedgerPreviousHash || null,
    eventLedgerRootHash: project.eventLedgerRootHash || null,
    eventLedgerFirstSequence: project.eventLedgerFirstSequence || 0,
    eventLedgerLastSequence: project.eventLedgerLastSequence || 0,
    eventLedgerEventCount: project.eventLedgerEventCount || project.eventLedgerLastSequence || 0,
  };
}

function projectFromEventSnapshot(project = {}, snapshot = {}) {
  return {
    ...project,
    eventLedger: structuredClone(snapshot.eventLedger || []),
    eventLedgerChainVersion: snapshot.eventLedgerChainVersion,
    eventLedgerPreviousHash: snapshot.eventLedgerPreviousHash,
    eventLedgerRootHash: snapshot.eventLedgerRootHash,
    eventLedgerFirstSequence: snapshot.eventLedgerFirstSequence,
    eventLedgerLastSequence: snapshot.eventLedgerLastSequence,
    eventLedgerEventCount: snapshot.eventLedgerEventCount,
    eventLedgerIntegrityStatus: 'valid',
  };
}

function verifyProjectEventSnapshot(snapshot = {}) {
  if (snapshot.schemaVersion !== 'local-project-event-snapshot/v1' || !snapshot.projectId || !Array.isArray(snapshot.eventLedger)) {
    return { valid: false, findings: [{ code: 'event-snapshot-shape-invalid', eventId: null }] };
  }
  return verifyProjectEventLedger(projectFromEventSnapshot({ id: snapshot.projectId }, snapshot));
}

function publicProjectEventCheckpoint(checkpoint = null) {
  if (!checkpoint) return null;
  return {
    schemaVersion: checkpoint.schemaVersion,
    id: checkpoint.id,
    projectId: checkpoint.projectId,
    status: checkpoint.status,
    contentChecksum: checkpoint.contentChecksum,
    checksum: checkpoint.checksum,
    eventCount: checkpoint.eventSnapshot?.eventLedgerEventCount || 0,
    retainedCount: checkpoint.eventSnapshot?.eventLedger?.length || 0,
    firstSequence: checkpoint.eventSnapshot?.eventLedgerFirstSequence || 0,
    lastSequence: checkpoint.eventSnapshot?.eventLedgerLastSequence || 0,
    rootHash: checkpoint.eventSnapshot?.eventLedgerRootHash || null,
    createdAt: checkpoint.createdAt,
    localOnly: true,
    externalWormStorage: false,
    idempotent: Boolean(checkpoint.idempotent),
  };
}

function validEventsAfterCheckpoint(checkpointSnapshot = {}, activeSnapshot = {}) {
  const candidates = (activeSnapshot.eventLedger || []).filter((event) => event.sequence > checkpointSnapshot.eventLedgerLastSequence);
  const valid = [];
  let previousHash = checkpointSnapshot.eventLedgerRootHash;
  let expectedSequence = checkpointSnapshot.eventLedgerLastSequence + 1;
  for (const event of candidates) {
    if (event.sequence !== expectedSequence) break;
    const probe = {
      id: checkpointSnapshot.projectId,
      eventLedger: [event],
      eventLedgerChainVersion: 1,
      eventLedgerPreviousHash: previousHash,
      eventLedgerRootHash: event.eventHash,
      eventLedgerFirstSequence: event.sequence,
      eventLedgerLastSequence: event.sequence,
    };
    if (!verifyProjectEventLedger(probe).valid) break;
    valid.push(event);
    previousHash = event.eventHash;
    expectedSequence += 1;
  }
  return valid;
}

function rebuildProjectEventLedger(project = {}, checkpointSnapshot = {}, validTail = []) {
  const combined = [...structuredClone(checkpointSnapshot.eventLedger || []), ...structuredClone(validTail)];
  const retained = combined.slice(-EVENT_LEDGER_RETAINED_LIMIT);
  const first = retained[0] || null;
  const last = retained.at(-1) || null;
  return {
    ...project,
    eventLedger: retained,
    eventLedgerChainVersion: 1,
    eventLedgerPreviousHash: first?.previousEventHash || checkpointSnapshot.eventLedgerPreviousHash,
    eventLedgerRootHash: last?.eventHash || checkpointSnapshot.eventLedgerPreviousHash,
    eventLedgerFirstSequence: first?.sequence || 0,
    eventLedgerLastSequence: last?.sequence || 0,
    eventLedgerEventCount: last?.sequence || checkpointSnapshot.eventLedgerEventCount || 0,
    eventLedgerIntegrityStatus: 'valid',
  };
}

export function resolveProjectChatTargets(text = '', team = []) {
  const normalized = text.toLowerCase();
  if (/@all\b/i.test(text)) return ['all'];
  const tokenTargets = [...text.matchAll(/@([A-Za-z0-9_-]+)/g)].map((match) => match[1].toLowerCase());

  return Array.from(new Set(team
    .filter((agent) => {
      const name = String(agent.name || '').toLowerCase();
      const id = String(agent.id || '').toLowerCase();
      return (name && normalized.includes(`@${name}`))
        || (id && normalized.includes(`@${id}`))
        || tokenTargets.includes(id)
        || name.split(/\s+/).some((part) => tokenTargets.includes(part));
    })
    .map((agent) => agent.name)));
}

export function createDirectorChatMessage({
  project = {},
  text = '',
  channelId = 'main',
  now = nowIso(),
  id = `m_${Date.now()}`,
  author = 'Director',
  authorId = null,
  source,
  targetIds = [],
  time = 'Now',
  weight,
  targets = resolveProjectChatTargets(text, project.team || []),
} = {}) {
  return attachMessageReceipts({
    id,
    projectId: project.id,
    channelId,
    type: targets.length ? 'mention' : 'text',
    author,
    authorId,
    source,
    time,
    text,
    targets,
    targetIds,
    weight: weight ?? (targets.length ? 'Raised' : null),
  }, project.team || [], { seenAt: now });
}

function transcriptChannelDefaults(channelId = 'main') {
  const id = slugPart(channelId || 'main');
  if (id === 'main') {
    return {
      name: 'Main',
      description: 'Default public project channel visible to the whole team.',
      category: 'text',
    };
  }
  if (id === 'google_chat') {
    return {
      name: 'Google Chat',
      description: 'External @mention bridge; change requests stay visible to the full project team.',
      category: 'text',
    };
  }
  if (id === 'decisions') {
    return {
      name: 'Decisions',
      description: 'Key decisions, confirmations, and change records.',
      category: 'decisions',
    };
  }
  const label = id
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (char) => char.toUpperCase());
  return {
    name: label || 'Project Room',
    description: 'Backend-created project collaboration channel visible to project members.',
    category: /voice|standup|call|room-audio/.test(id) ? 'voice' : 'text',
  };
}

function normalizeTranscriptChannel(input = {}) {
  const seed = input.channelId || input.id || input.name || 'project-room';
  const channelId = slugPart(seed).replace(/-/g, '_');
  const defaults = transcriptChannelDefaults(channelId);
  const category = ['text', 'decisions', 'voice'].includes(input.category)
    ? input.category
    : defaults.category;
  return {
    schemaVersion: 'transcript-channel/v1',
    channelId,
    id: channelId,
    name: String(input.name || defaults.name || channelId).trim(),
    description: String(input.description || defaults.description || 'Project collaboration channel.').trim(),
    category,
    apiPath: input.projectId ? `/projects/${input.projectId}/transcripts/${encodeURIComponent(channelId)}` : null,
  };
}

export function createProjectTranscriptChannel({
  project = {},
  messages = [],
  channelId = '',
  name = '',
  description = '',
  category = 'text',
  now = nowIso(),
  actor = 'Director',
  actorId = 'director',
  source = 'backend-transcript-channel-create',
  messageId,
} = {}) {
  const existingIndex = buildTranscriptIndex({ project, messages });
  const requestedChannel = normalizeTranscriptChannel({
    projectId: project.id,
    channelId: channelId || name || `room_${(existingIndex.channels || []).length + 1}`,
    name,
    description,
    category,
  });
  const existingChannel = (existingIndex.channels || [])
    .find((channel) => String(channel.channelId || '') === requestedChannel.channelId);
  if (existingChannel) {
    return {
      project,
      messages: [],
      route: 'transcript-channel-existing',
      transcriptChannel: {
        ...requestedChannel,
        ...existingChannel,
        schemaVersion: 'transcript-channel/v1',
      },
      transcriptChannelReceipt: {
        schemaVersion: 'transcript-channel-existing/v1',
        projectId: project.id || null,
        channelId: requestedChannel.channelId,
        route: project.id ? `/projects/${project.id}/transcripts/${encodeURIComponent(requestedChannel.channelId)}` : null,
      },
    };
  }

  const timestamp = Date.parse(now) || Date.now();
  const channelRoute = project.id ? `/projects/${project.id}/transcripts/${encodeURIComponent(requestedChannel.channelId)}` : null;
  const generatedMessageId = messageId || `transcript_channel_created_${requestedChannel.channelId}_${timestamp}`;
  const logId = `log_${generatedMessageId}`;
  const eventId = `evt_transcript_channel_created_${requestedChannel.channelId}_${timestamp}`;
  const receiptBase = {
    schemaVersion: 'transcript-channel-created/v1',
    id: `transcript_channel_receipt_${project.id || 'project'}_${requestedChannel.channelId}_${timestamp}`,
    projectId: project.id || null,
    channelId: requestedChannel.channelId,
    name: requestedChannel.name,
    description: requestedChannel.description,
    category: requestedChannel.category,
    actor,
    actorId,
    source,
    createdAt: now,
    messageId: generatedMessageId,
    timelineLogId: logId,
    eventId,
    route: channelRoute,
  };
  const transcriptChannelReceipt = {
    ...receiptBase,
    checksum: persistenceChecksum(receiptBase),
  };
  const systemMessage = attachMessageReceipts({
    id: generatedMessageId,
    projectId: project.id || null,
    channelId: requestedChannel.channelId,
    type: 'system',
    schemaVersion: 'transcript-channel-created-message/v1',
    author: 'System',
    authorId: 'system',
    source,
    time: 'Channel Created',
    text: `${actor || 'Director'} created #${requestedChannel.name}: ${requestedChannel.description}`,
    targets: ['all'],
    targetIds: (project.team || []).map((agent) => agent.id).filter(Boolean),
    weight: 'Channel Created',
    channelName: requestedChannel.name,
    channelCategory: requestedChannel.category,
    transcriptChannel: requestedChannel,
    transcriptChannelReceiptId: transcriptChannelReceipt.id,
    transcriptChannelReceiptChecksum: transcriptChannelReceipt.checksum,
  }, project.team || [], { seenAt: now, broadcast: true });
  const log = {
    id: logId,
    messageId: generatedMessageId,
    time: now,
    agent: actor || 'Director',
    actor: actor || 'Director',
    agentId: actorId || null,
    eventType: 'transcript-channel-created',
    source,
    channelId: requestedChannel.channelId,
    sourceChannelId: requestedChannel.channelId,
    log: systemMessage.text,
    transcriptChannelId: requestedChannel.channelId,
    transcriptChannelName: requestedChannel.name,
    transcriptChannelReceiptId: transcriptChannelReceipt.id,
    checksum: transcriptChannelReceipt.checksum,
  };
  const projectWithChannel = appendProjectEvents({
    ...project,
    transcriptChannelReceipts: [
      transcriptChannelReceipt,
      ...(project.transcriptChannelReceipts || []),
    ].slice(0, 120),
    logs: [log, ...(project.logs || [])],
  }, [
    createProjectLedgerEvent({
      id: eventId,
      type: 'transcript-channel-created',
      time: now,
      actor: actor || 'Director',
      summary: systemMessage.text,
      source,
      channelId: requestedChannel.channelId,
      evidenceIds: [generatedMessageId, logId, transcriptChannelReceipt.id, transcriptChannelReceipt.checksum].filter(Boolean),
      entityIds: {
        projectId: project.id || null,
        channelId: requestedChannel.channelId,
        messageId: generatedMessageId,
        logId,
        transcriptChannelReceiptId: transcriptChannelReceipt.id,
      },
      payload: {
        schemaVersion: transcriptChannelReceipt.schemaVersion,
        channel: requestedChannel,
        receiptChecksum: transcriptChannelReceipt.checksum,
      },
    }),
  ]);

  return {
    project: projectWithChannel,
    messages: [{ ...systemMessage, projectId: project.id }],
    route: 'transcript-channel-created',
    transcriptChannel: {
      ...requestedChannel,
      createdAt: now,
      messageId: generatedMessageId,
      timelineLogId: logId,
      eventId,
      receiptId: transcriptChannelReceipt.id,
      checksum: transcriptChannelReceipt.checksum,
    },
    transcriptChannelReceipt,
    log,
  };
}

export function pinProjectTranscriptMessage({
  project = {},
  messages = [],
  channelId = 'main',
  messageId = '',
  reason = '',
  pinnedBy = 'Director',
  pinnedById = 'director',
  now = nowIso(),
  source = 'backend-transcript-pin',
} = {}) {
  const scopedChannelId = String(channelId || 'main').trim() || 'main';
  const targetMessageId = String(messageId || '').trim();
  if (!targetMessageId) throw new Error('transcript-message-id-required');

  const transcript = buildChannelTranscript({ project, messages, channelId: scopedChannelId });
  const transcriptMessages = [
    ...(transcript.messages || []),
    ...(transcript.archivedProofMessages || []),
  ];
  const pinnedMessage = transcriptMessages.find((message) => String(message.id || '') === targetMessageId);
  if (!pinnedMessage) throw new Error(`Transcript message not found: ${targetMessageId}`);

  const timestamp = Date.parse(now) || Date.now();
  const safeMessageKey = slugPart(targetMessageId).slice(0, 72);
  const pinId = `transcript_pin_${scopedChannelId}_${safeMessageKey}_${timestamp}`;
  const pinMessageId = `transcript_pin_message_${scopedChannelId}_${safeMessageKey}_${timestamp}`;
  const timelineLogId = `log_${pinMessageId}`;
  const eventId = `evt_transcript_message_pinned_${scopedChannelId}_${timestamp}`;
  const pinRoute = project.id
    ? `/projects/${project.id}/transcripts/${encodeURIComponent(scopedChannelId)}#${encodeURIComponent(targetMessageId)}`
    : null;
  const pinReason = String(reason || '').trim() || 'Pinned for Manager review.';
  const messageText = String(pinnedMessage.text || pinnedMessage.meta || '');
  const receiptBase = {
    schemaVersion: 'transcript-pin/v1',
    id: pinId,
    projectId: project.id || null,
    channelId: scopedChannelId,
    messageId: targetMessageId,
    pinMessageId,
    pinnedBy,
    pinnedById,
    pinnedAt: now,
    reason: pinReason,
    messageAuthor: pinnedMessage.author || 'Unknown',
    messageAuthorId: pinnedMessage.authorId || null,
    messageType: pinnedMessage.type || 'message',
    messageTime: pinnedMessage.time || null,
    messageTextPreview: compactPreview(messageText, 180),
    messageTextChecksum: persistenceChecksum(messageText),
    timelineLogId,
    eventId,
    apiPath: pinRoute,
    transcriptRoute: project.id ? `/projects/${project.id}/transcripts/${encodeURIComponent(scopedChannelId)}` : null,
    active: true,
    readyForProduction: false,
    productionBlockerReason: 'Transcript pins are local MVP proof records; production requires managed retention, tenant policy, and centralized audit controls.',
  };
  const transcriptPinReceipt = {
    ...receiptBase,
    proofIds: uniqueStrings([targetMessageId, pinMessageId, pinId].filter(Boolean)),
    checksum: persistenceChecksum(receiptBase),
  };
  const systemMessage = attachMessageReceipts({
    id: pinMessageId,
    projectId: project.id || null,
    channelId: scopedChannelId,
    type: 'system',
    schemaVersion: 'transcript-pin-message/v1',
    author: 'System',
    authorId: 'system',
    source,
    time: 'Pinned',
    text: `${pinnedBy || 'Director'} pinned ${pinnedMessage.author || 'a message'}: ${pinReason}`,
    targets: ['all'],
    targetIds: (project.team || []).map((agent) => agent.id).filter(Boolean),
    weight: 'Pinned',
    pinnedMessageId: targetMessageId,
    transcriptPinReceiptId: transcriptPinReceipt.id,
    transcriptPinReceiptChecksum: transcriptPinReceipt.checksum,
  }, project.team || [], { seenAt: now, broadcast: true });
  const log = {
    id: timelineLogId,
    messageId: pinMessageId,
    pinnedMessageId: targetMessageId,
    time: now,
    agent: pinnedBy || 'Director',
    actor: pinnedBy || 'Director',
    agentId: pinnedById || null,
    eventType: 'transcript-message-pinned',
    source,
    channelId: scopedChannelId,
    sourceChannelId: scopedChannelId,
    log: `${pinnedBy || 'Director'} pinned transcript message ${targetMessageId}: ${pinReason}`,
    transcriptPinReceiptId: transcriptPinReceipt.id,
    checksum: transcriptPinReceipt.checksum,
  };
  const existingReceipts = (project.transcriptPinReceipts || [])
    .filter((receipt) => !(
      String(receipt.channelId || 'main') === scopedChannelId
      && String(receipt.messageId || '') === targetMessageId
      && receipt.active !== false
    ));
  const projectWithPin = appendProjectEvents({
    ...project,
    transcriptPinReceipts: [
      transcriptPinReceipt,
      ...existingReceipts,
    ].slice(0, TRANSCRIPT_PIN_RECEIPT_LIMIT),
    logs: [log, ...(project.logs || [])],
  }, [
    createProjectLedgerEvent({
      id: eventId,
      type: 'transcript-message-pinned',
      time: now,
      actor: pinnedBy || 'Director',
      summary: log.log,
      source,
      channelId: scopedChannelId,
      evidenceIds: [
        targetMessageId,
        pinMessageId,
        timelineLogId,
        transcriptPinReceipt.id,
        transcriptPinReceipt.checksum,
      ].filter(Boolean),
      entityIds: {
        projectId: project.id || null,
        channelId: scopedChannelId,
        messageId: pinMessageId,
        pinnedMessageId: targetMessageId,
        logId: timelineLogId,
        transcriptPinReceiptId: transcriptPinReceipt.id,
      },
      payload: {
        schemaVersion: transcriptPinReceipt.schemaVersion,
        reason: pinReason,
        pinnedMessageAuthor: pinnedMessage.author || null,
        receiptChecksum: transcriptPinReceipt.checksum,
      },
    }),
  ]);

  return {
    project: projectWithPin,
    messages: [{ ...systemMessage, projectId: project.id }],
    route: 'transcript-message-pinned',
    transcriptPin: transcriptPinReceipt,
    transcriptPinReceipt,
    pinnedMessage,
    log,
  };
}

