        channelId: 'manager-dashboard',
        actionId: row.id,
        requirementId: row.requirementId,
        actionLabel: row.label,
        route: row.runApiPath || `/projects/${projectId}/manager-action-queue/${encodeURIComponent(actionKey)}/run`,
